package com.arenashowdown.lobby;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.Action;import org.bukkit.event.inventory.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.*;import java.util.*;
final class LobbyItems implements Listener{
 private final ArenaLobbyPlugin plugin;private final NamespacedKey key;
 LobbyItems(ArenaLobbyPlugin plugin){this.plugin=plugin;key=new NamespacedKey(plugin,"navigation");}
 void give(Player p){if(!plugin.getConfig().getBoolean("hotbar.enabled",true)||has(p,"menu"))return;give(p,"menu",Material.COMPASS,plugin.getConfig().getInt("hotbar.menu.slot",4),plugin.getConfig().getString("hotbar.menu.name","&6✦ Arena Showdown &8• &fMinigames"),plugin.getConfig().getStringList("hotbar.menu.lore"));if(plugin.getConfig().getBoolean("hotbar.info.enabled",true))give(p,"info",Material.BOOK,plugin.getConfig().getInt("hotbar.info.slot",0),"&eInformacoes do campeonato",List.of("&7Clique para consultar o status."));if(plugin.getConfig().getBoolean("hotbar.ranking.enabled",true))give(p,"ranking",Material.GOLD_INGOT,plugin.getConfig().getInt("hotbar.ranking.slot",8),"&6Ranking geral",List.of("&7Clique para consultar a classificacao."));}
 private void give(Player p,String action,Material type,int preferred,String name,List<String>lore){if(has(p,action))return;int slot=preferred>=0&&preferred<9&&p.getInventory().getItem(preferred)==null?preferred:p.getInventory().firstEmpty();if(slot<0){p.sendMessage(plugin.text("&eNao foi possivel entregar a navegacao: inventario cheio."));return;}ItemStack i=new ItemStack(type);ItemMeta m=i.getItemMeta();m.displayName(plugin.text(name));m.lore(lore.stream().map(plugin::text).toList());m.getPersistentDataContainer().set(key,PersistentDataType.STRING,action);i.setItemMeta(m);p.getInventory().setItem(slot,i);}
 void remove(Player p){for(int i=0;i<p.getInventory().getSize();i++)if(action(p.getInventory().getItem(i))!=null)p.getInventory().setItem(i,null);}
 private boolean has(Player p,String value){return Arrays.stream(p.getInventory().getContents()).anyMatch(i->value.equals(action(i)));}
 private String action(ItemStack i){return i==null||!i.hasItemMeta()?null:i.getItemMeta().getPersistentDataContainer().get(key,PersistentDataType.STRING);}
 @EventHandler public void use(PlayerInteractEvent e){String a=action(e.getItem());if(a==null||!plugin.isLobby(e.getPlayer().getWorld()))return;if(e.getAction()==Action.PHYSICAL)return;e.setCancelled(true);switch(a){case"menu"->plugin.menu().open(e.getPlayer());case"ranking"->e.getPlayer().performCommand("arena ranking "+plugin.championship());case"info"->e.getPlayer().performCommand("arena status "+plugin.championship());}}
 @EventHandler public void drop(PlayerDropItemEvent e){if(action(e.getItemDrop().getItemStack())!=null)e.setCancelled(true);}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||!plugin.isLobby(p.getWorld()))return;if(action(e.getCurrentItem())!=null||action(e.getCursor())!=null)e.setCancelled(true);}
 @EventHandler public void drag(InventoryDragEvent e){if(e.getWhoClicked() instanceof Player p&&plugin.isLobby(p.getWorld())&&action(e.getOldCursor())!=null)e.setCancelled(true);}
}
